-- Restore, part 1 (L0): stop everything that runs, put the SAP side back from the zero-copy
-- baseline and rebuild the CLD stand-in. Then run 71, 71n, 72 and 79_idle.sql
-- (tools/schema_change_demo.py restore does all of this in order).
alter alert if exists {{DEMO_DB}}.CONTROL.ALERT_SCHEMA_GUARD suspend;
alter task if exists {{DEMO_DB}}.CONTROL.STATUS_SNAPSHOT_TASK suspend;
alter task if exists {{DEMO_L0}}.SYNC.SYNC_L0 suspend;

create or replace schema {{DEMO_L0}}.PUBLISHER clone {{DEMO_L0}}.BASELINE
  comment = 'SAP side: the data product as published. Scenarios change this schema.';
create or replace schema {{DEMO_L0}}.MAINTENANCE comment = 'CLD stand-in: what Snowflake sees after sync. Never edited by hand.';
update {{DEMO_L0}}.SYNC.L0_SYNC_STATE set LAST_SYNC_AT = null, LAST_ACTIONS = null;
truncate table {{DEMO_L0}}.SYNC.SYNC_LOG;
call {{DEMO_L0}}.SYNC.SP_SYNC_L0();

create or replace view {{DEMO_L0}}.MAINTENANCE.V_NOTIFICATION_EQUIPMENT as
select n.MAINTENANCENOTIFICATION, n.CREATEDON, n.DOWNTIMEHOURS, n.NOTIFICATIONTEXT, e.EQUIPMENTNAME, e.PLANT, e.FLEETTYPE
from {{DEMO_L0}}.MAINTENANCE.MAINT_NOTIFICATION n
join {{DEMO_L0}}.MAINTENANCE.EQUIPMENT e on e.EQUIPMENT = n.EQUIPMENT;

drop dynamic table if exists {{DEMO_DB}}.L2.DT_EQUIPMENT_DOWNTIME_V2;
drop table if exists {{DEMO_DB}}.L2.DOWNTIME_RETAINED;
